/**
 * ============================================================================
 * Fayzar Layout Engine - Gemini Markdown Prompt Factory v1.0
 * ============================================================================
 * Generates tailored, zero-hallucination, structured markdown prompts for Gemini AI
 * to ensure that text extracted from images/PDFs or generated by AI conforms 100%
 * to the Layout Engine's expected markdown schema.
 * ============================================================================
 */

(function(global) {
  'use strict';

  class GeminiPromptFactory {

    /**
     * Get system instruction and markdown prompt for a given layout template ID
     * @param {string} templateId - One of the 9 template IDs
     * @param {Object} overrides - Custom metadata options
     * @returns {Object} { templateId, title, promptText, exampleMarkdown }
     */
    static getPrompt(templateId, overrides = {}) {
      const templates = global.LAYOUT_TEMPLATES || {};
      const template = templates[templateId] || templates['question-2col'];

      let specificInstructions = '';

      switch (templateId) {
        case 'question-2col':
        case 'creative-cq':
          specificInstructions = `
1. QUESTION NUMBERING & MARKS ALIGNMENT:
   - Use Bengali sequential numbering with '।' (e.g. ১।, ২।, ৩।, ... ১০।).
   - For creative sub-questions, use '(ক)', '(খ)', '(গ)', '(ঘ)'.
   - Put the full marks in square brackets at the very right of the line (e.g. [১], [২], [৩], [৪] or [১০]).
   - For creative stimulus/passage, prefix with 'উদ্দীপক:' or format as a blockquote '> উদ্দীপক লেখা...'.

2. FRONTMATTER HEADER SPECIFICATION:
   Extract or specify the header metadata at the very beginning between '---' delimiters:
   ---
   institute: [প্রতিষ্ঠানের নাম]
   exam: [পরীক্ষার নাম]
   grade: [শ্রেণি]
   subject: [বিষয়]
   time: [সময়]
   fullMarks: [পূর্ণমান]
   note: [বিশেষ দ্রষ্টব্য]
   columns: ${template.columns || 2}
   ---
`;
          break;

        case 'mcq-grid':
          specificInstructions = `
1. MCQ QUESTION & 4-OPTION STRUCTURE:
   - Each question starts with: ১।, ২।, ৩।, ...
   - Exactly 4 options per question on the next line or same line formatted as:
     (ক) অপশন ১  (খ) অপশন ২  (গ) অপশন ৩  (ঘ) অপশন ৪
   - If options contain mathematical symbols or numbers, keep digits accurate.

2. FRONTMATTER HEADER:
   ---
   institute: [প্রতিষ্ঠানের নাম]
   exam: [পরীক্ষার নাম]
   grade: [শ্রেণি]
   subject: [বিষয়]
   time: [সময়]
   fullMarks: [পূর্ণমান]
   note: প্রতিটি প্রশ্নের মান ১। সঠিক উত্তরের বৃত্ত ভরাট করো।
   columns: 2
   ---
`;
          break;

        case 'math-science':
          specificInstructions = `
1. MATHEMATICAL FORMULAS & LATEX PRECISION:
   - Enclose inline math expressions in single dollar signs: $x = \\frac{-b \\pm \\sqrt{b^2-4ac}}{2a}$
   - Enclose block math equations in double dollar signs: $$\\int_{0}^{\\pi} \\sin(x) dx = 2$$
   - Preserve square roots (\\sqrt{x}), fractions (\\frac{a}{b}), exponents (x^2), subscripts (a_n), and Greek letters (\\alpha, \\beta, \\theta).
   - If there is a geometric diagram, circuit or figure, write: [চিত্র-০১] (or page reference [ছবি আছে-পৃ:০১]).
`;
          break;

        case 'official-notice':
          specificInstructions = `
1. OFFICIAL MEMO & NOTICE FORMAT:
   ---
   institute: [গণপ্রজাতন্ত্রী বাংলাদেশ সরকার / প্রতিষ্ঠানের নাম]
   subHeader: [দপ্তর / কার্যালয় ও ঠিকানা]
   memoNo: [স্মারক নম্বর]
   date: [তারিখ]
   subject: [নোটিশের মূল বিষয়]
   layout: official-notice
   ---
2. BODY AND SIGNATURE:
   - Body paragraphs separated by single blank lines.
   - Numbered action points (1, 2, 3...) if any.
   - At the bottom, include:
     **স্বাক্ষরিত:**
     (কর্মকর্তার নাম)
     পদবি ও দপ্তর
     ফোন ও ইমেইল
   - Distribution / Copy list:
     **অনুলিপি সদয় অবগতি ও প্রয়োজনীয় কার্যার্থে প্রেরিত হলো:**
     ১. ...
     ২. ...
`;
          break;

        case 'tabulation-sheet':
          specificInstructions = `
1. TABULATION & MARKSHEET TABLE FORMAT:
   ---
   institute: [প্রতিষ্ঠানের নাম]
   title: [পরীক্ষার ফলাফল ও ট্যাবুলেশন শিট]
   grade: [শ্রেণি ও শাখা]
   orientation: landscape
   layout: tabulation-sheet
   ---
2. TABLE SPECIFICATION:
   Output standard markdown table:
   | রোল | শিক্ষার্থীর নাম | বিষয় ১ | বিষয় ২ | মোট নম্বর | জিপিএ | গ্রেড |
   | :---: | :--- | :---: | :---: | :---: | :---: | :---: |
   | ০১ | ... | ৮৫ | ৯০ | ... | ৫.০০ | A+ |
`;
          break;

        case 'testimonial-cert':
          specificInstructions = `
1. TESTIMONIAL & CERTIFICATE FORMAT:
   ---
   institute: [প্রতিষ্ঠানের নাম]
   address: [প্রতিষ্ঠানের ঠিকানা]
   serialNo: [স্মারক / ক্রমিক নম্বর]
   date: [তারিখ]
   title: প্রত্যয়নপত্র / প্রশংসাপত্র
   layout: testimonial-cert
   ---
2. CERTIFICATE BODY:
   - Formal Bengali testimonial language ("এই মর্মে প্রত্যয়ন করা যাচ্ছে যে...").
   - Highlight student name, father name, mother name, roll, reg, GPA in bold (**নাম**).
   - Bottom block: Principal's signature and seal placeholder.
`;
          break;

        case 'biodata-cv':
          specificInstructions = `
1. CV / BIODATA STRUCTURE:
   ---
   fullName: [প্রার্থীর নাম]
   profession: [পেশা / পদবি]
   mobile: [মোবাইল নম্বর]
   email: [ইমেইল]
   address: [ঠিকানা]
   layout: biodata-cv
   ---
2. SECTION TABLES:
   - Personal Information table (| বিবরণ | তথ্যাবলী |)
   - Educational Qualifications table (| পরীক্ষার নাম | বোর্ড | পাশের সন | বিভাগ | জিপিএ |)
   - Skills & Declaration
`;
          break;

        case 'legal-deed':
          specificInstructions = `
1. LEGAL STAMP DEED FORMAT:
   ---
   title: [দলিল / চুক্তিপত্রের শিরোনাম]
   stampValue: [স্ট্যাম্পের মূল্যমান]
   deedDate: [তারিখ]
   pageSize: legal
   stampMarginInches: 4.0
   layout: legal-deed
   ---
2. DEED CLAUSES:
   - Top 4 inches reserved for Non-Judicial Stamp.
   - First Party (১ম পক্ষ) and Second Party (২য় পক্ষ) details.
   - Numbered numbered legal clauses (১. চুক্তির মেয়াদ, ২. ভাড়ার হার...).
   - Witness and Signatures table at bottom.
`;
          break;
      }

      const fullPrompt = `You are a Professional Document Layout Expert and Bengali Markdown Architect for "Fayzar Layout Engine".
Your goal is to transcribe images/PDFs OR generate a structured, flawless Bengali document strictly adhering to the specified layout format: "${template.name}".

================================================================================
CRITICAL FORMATTING & LAYOUT RULES FOR THIS DOCUMENT:
================================================================================
${specificInstructions}

================================================================================
UNIVERSAL ACCURACY & FIDELITY MANDATES:
================================================================================
1. STRICT SOURCE FIDELITY:
   - Never invent, fabricate or guess missing questions, marks or headers that are not in the source.
   - If handwritten or printed, transcribe stroke-by-stroke with surgical precision.

2. LANGUAGE & SCRIPT INTEGRITY:
   - If English words, chemical formulas (H2O, FeCl3), units (cm, mL), or computer terms appear, KEEP THEM IN PURE ASCII ENGLISH.
   - Maintain numeral scripts: Bengali digits (১, ২, ৩) stay Bengali; English digits (1, 2, 3) stay English.

3. CLEAN MARKDOWN OUTPUT ONLY:
   - Start immediately with the YAML frontmatter block '---'.
   - Do NOT wrap output in triple backtick markdown fences (\`\`\`markdown).
   - Do NOT write conversational fluff, pleasantries, or explanations.
   - Ensure the markdown is directly ready to be parsed by the Fayzar Layout Studio.

Now process and generate the complete structured Markdown:`;

      return {
        templateId: templateId,
        templateName: template.name,
        promptText: fullPrompt.trim(),
        sampleMarkdown: template.sampleMarkdown || ''
      };
    }

    /**
     * Get all available template prompt choices
     */
    static getAllTemplateChoices() {
      const templates = global.LAYOUT_TEMPLATES || {};
      return Object.keys(templates).map(id => ({
        id: id,
        name: templates[id].name,
        category: templates[id].category,
        columns: templates[id].columns
      }));
    }
  }

  // Export to global scope
  global.GeminiPromptFactory = GeminiPromptFactory;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = GeminiPromptFactory;
  }
})(typeof window !== 'undefined' ? window : this);
